sql.where:
AND DELETED = 0

    AND ASSET_TYPE = #{assetType}


    AND ASSET_CATEGORY = #{assetCategory}


    AND ASSET_NATURE = #{assetNature}


    AND ASSET_STATUS = #{assetStatus}


    AND ASSET_QUALITY_LEVEL = #{assetQualityLevel}


    AND ASSET_RISK_LEVEL = #{assetRiskLevel}


    AND ENTERPRISE_ID = #{enterpriseId}


    AND ASSET_REGION = #{assetRegion}


    AND ASSET_INDUSTRY = #{assetIndustry}


    AND ASSET_MANAGER = #{assetManager}


    AND MANAGEMENT_DEPARTMENT = #{managementDepartment}


    AND IS_CORE_ASSET = #{isCoreAsset}


    AND IS_STRATEGIC_ASSET = #{isStrategicAsset}


    AND IS_IDLE_ASSET = #{isIdleAsset}


    AND IS_PLEDGED = #{isPledged}


    AND NEED_REGULATORY_ATTENTION = #{needRegulatoryAttention}


    AND ORIGINAL_VALUE >= #{minOriginalValue}


    AND ORIGINAL_VALUE <= #{maxOriginalValue}


    AND NET_VALUE >= #{minNetValue}


    AND NET_VALUE <= #{maxNetValue}


    AND MARKET_VALUE >= #{minMarketValue}


    AND MARKET_VALUE <= #{maxMarketValue}


    AND ASSET_RETURN_RATE >= #{minReturnRate}


    AND ASSET_RETURN_RATE <= #{maxReturnRate}


    AND ASSET_TURNOVER_RATE >= #{minTurnoverRate}


    AND ASSET_TURNOVER_RATE <= #{maxTurnoverRate}


    AND ASSET_UTILIZATION_RATE >= #{minUtilizationRate}


    AND ASSET_UTILIZATION_RATE <= #{maxUtilizationRate}


    AND ASSET_NAME LIKE CONCAT('%', #{assetName}, '%')


    AND ASSET_CODE LIKE CONCAT('%', #{assetCode}, '%')

mapper.delete:
DELETE FROM ASSET_INFO WHERE DELETED = 1 AND UPDATE_TIME <
DATE_SUB(NOW(), INTERVAL #{days} DAY)
SYSDATE - #{days}
